# The OAuth consent screen (generated by maquina:oauth): the only OAuth
# endpoint that uses the session cookie. A signed-out visitor goes through
# Clave's sign-in, which stores the whole request.url, query string included,
# and lands back here after the email code.
#
# Until the client and its redirect_uri are known to be genuine, errors are a
# page on this site (400), never a redirect: a redirect would hand the
# visitor to an address nobody vouched for. After that, every error goes
# back to the client with error, state and iss (RFC 9207).
class Oauth::AuthorizationsController < ApplicationController
  OAUTH_PARAMS = %i[response_type client_id redirect_uri code_challenge code_challenge_method scope state resource].freeze

  # Each new client_id is an outbound fetch; a signed-in person asking for
  # dozens a minute is not signing in to apps.
  rate_limit to: 20, within: 1.minute, only: :new, with: -> { head :too_many_requests }

  before_action :set_client, :verify_redirect_uri
  before_action :require_mcp_enabled, :verify_authorization_request

  # GET /oauth/authorize
  def new
    @oauth_params = oauth_params.merge(scope: @scope)
  end

  # POST /oauth/authorize
  def create
    if params[:decision] == "allow"
      code = OauthAuthorizationCode.issue!(user: Current.user, client: @client, redirect_uri: @redirect_uri,
        code_challenge: params[:code_challenge], scope: @scope, resource: params[:resource])
      Rails.logger.info "[OAUTH] Access granted to #{@client.client_id} (#{@scope}) by #{Current.user.email_address}"
      redirect_to_client code: code
    else
      Rails.logger.info "[OAUTH] Access denied to #{@client.client_id} by #{Current.user.email_address}"
      redirect_to_client error: "access_denied"
    end
  end

  private

  def oauth_params
    params.permit(*OAUTH_PARAMS).to_h.symbolize_keys
  end

  def set_client
    @client = OauthClient.from_metadata!(params[:client_id].to_s)
  rescue OauthClient::MetadataFetcher::Refused, ActiveRecord::RecordInvalid => error
    Rails.logger.info "[OAUTH] Client refused (#{error.message}): #{params[:client_id].to_s.truncate(200)}"
    render_error :unknown_client
  end

  def verify_redirect_uri
    @redirect_uri = params[:redirect_uri].to_s
    render_error :redirect_mismatch unless @client.redirect_uri?(@redirect_uri)
  end

  def require_mcp_enabled
    redirect_to_client error: "access_denied", error_description: "Not available for this account" unless Mcp.enabled_for?(Current.user)
  end

  def verify_authorization_request
    @scope = AccessToken.normalize_scope(params[:scope])

    if params[:response_type] != "code"
      redirect_to_client error: "unsupported_response_type", error_description: "response_type must be code"
    elsif params[:code_challenge].blank?
      redirect_to_client error: "invalid_request", error_description: "code_challenge is required"
    elsif params[:code_challenge_method] != "S256"
      redirect_to_client error: "invalid_request", error_description: "code_challenge_method must be S256"
    elsif params[:resource] != mcp_resource
      redirect_to_client error: "invalid_target", error_description: "resource must be #{mcp_resource}"
    elsif @scope.nil?
      redirect_to_client error: "invalid_scope", error_description: "scope must be read, write or both"
    end
  end

  def mcp_resource
    "#{request.base_url}/mcp"
  end

  # Back to the client's own redirect_uri, keeping any query it already has.
  def redirect_to_client(**response_params)
    uri = URI(@redirect_uri)
    response_params = response_params.merge(state: params[:state].presence, iss: request.base_url).compact
    uri.query = URI.encode_www_form(URI.decode_www_form(uri.query.to_s) + response_params.to_a)
    redirect_to uri.to_s, allow_other_host: true, status: :see_other
  end

  def render_error(reason)
    @reason = reason
    render :error, status: :bad_request
  end
end
